/**
 * Build Solar Line Duotone icon assets.
 *
 * Source: the iconify-json solar package (CC BY 4.0). Add a name to ICONS, then run
 * `bun run icons`. Generated files must never be edited by hand:
 * - assets/icons/solar-line-duotone.json  (PHP sekeco_icon(), editor window.sekecoIcons)
 * - assets/admin/menu-icons.css           (CPT admin menu icons)
 * - ../../themes/sekeco/assets/css/solar-icons.css (CSS mask classes)
 */
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve( dirname( fileURLToPath( import.meta.url ) ), '..' );
const solar = JSON.parse(
	readFileSync(
		resolve( root, 'node_modules/@iconify-json/solar/icons.json' ),
		'utf8'
	)
);

const ICONS = [
	'arrow-right',
	'arrow-right-up',
	'arrow-left',
	'arrow-down',
	'arrow-up',
	'alt-arrow-down',
	'alt-arrow-up',
	'alt-arrow-left',
	'alt-arrow-right',
	'double-alt-arrow-down',
	'sun-2',
	'moon',
	'hamburger-menu',
	'close-circle',
	'close-square',
	'add-circle',
	'minus-circle',
	'check-circle',
	'magnifer',
	'link-round',
	'global',
	'letter',
	'phone',
	'map-point',
	'plain',
	'play',
	'mouse-circle',
	'code-square',
	'programming',
	'smartphone',
	'cart-large-2',
	'server-square',
	'database',
	'palette-round',
	'layers',
	'compass',
	'rocket',
	'bolt',
	'shield-check',
	'hand-heart',
	'diagram-up',
	'clipboard-list',
	'chat-round-dots',
	'calendar',
	'tag',
	'user-rounded',
	'widget-4',
	'align-left',
	'notes',
	'repeat',
	'case-round',
	'box',
	'users-group-rounded',
	'document-add',
	'inbox-in',
];

const out = {};

for ( const name of ICONS ) {
	const icon = solar.icons[ `${ name }-line-duotone` ];

	if ( ! icon ) {
		throw new Error( `Missing Solar icon: ${ name }-line-duotone` );
	}

	out[ name ] = icon.body;
}

const svg = ( body ) =>
	`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="#000" color="#000">${ body }</svg>`;
const dataUri = ( body ) =>
	`url("data:image/svg+xml,${ encodeURIComponent(
		svg( body.replaceAll( 'currentColor', '#000' ) )
	) }")`;

mkdirSync( resolve( root, 'assets/icons' ), { recursive: true } );
writeFileSync(
	resolve( root, 'assets/icons/solar-line-duotone.json' ),
	JSON.stringify( out, null, '\t' ) + '\n'
);

// CPT admin menu icons.
const menu = {
	portfolio: 'case-round',
	product: 'box',
	team: 'users-group-rounded',
	sekeco_form: 'document-add',
	sekeco_submission: 'inbox-in',
};
let adminCss = '/* Generated by scripts/build-icons.mjs. Do not edit. */\n';
for ( const [ type, icon ] of Object.entries( menu ) ) {
	adminCss += `#adminmenu .menu-icon-${ type } div.wp-menu-image::before,\n#adminmenu .menu-icon-${ type } div.wp-menu-image.dashicons-before::before {\n\tcontent: "";\n\tdisplay: block;\n\twidth: 20px;\n\theight: 20px;\n\tmargin: 7px auto 0;\n\tbackground-color: currentColor;\n\t-webkit-mask: ${ dataUri( out[ icon ] ) } center / contain no-repeat;\n\tmask: ${ dataUri( out[ icon ] ) } center / contain no-repeat;\n\tfont-family: inherit;\n}\n`;
}
mkdirSync( resolve( root, 'assets/admin' ), { recursive: true } );
writeFileSync( resolve( root, 'assets/admin/menu-icons.css' ), adminCss );

// Theme CSS mask classes.
let themeCss =
	'/* Generated by plugin scripts/build-icons.mjs (Solar Line Duotone, CC BY 4.0). Do not edit. */\n.sekeco-icon {\n\tdisplay: inline-block;\n\tflex: none;\n\twidth: 1.25em;\n\theight: 1.25em;\n\tvertical-align: -0.25em;\n\tbackground-color: currentColor;\n\t-webkit-mask: var(--sekeco-icon) center / contain no-repeat;\n\tmask: var(--sekeco-icon) center / contain no-repeat;\n}\n';
for ( const [ name, body ] of Object.entries( out ) ) {
	themeCss += `.sekeco-icon--${ name } {\n\t--sekeco-icon: ${ dataUri( body ) };\n}\n`;
}
// Core controls whose built-in glyph is replaced by a Solar icon.
const BINDINGS = [
	{
		selector:
			'.sekeco-header .wp-block-navigation__responsive-container-open',
		icon: 'hamburger-menu',
	},
	{
		selector: '.wp-block-navigation-overlay-close',
		icon: 'close-circle',
	},
	{
		// Row arrow in the drawer menu: drawn after the link text, not replacing a glyph.
		selector: '.sk-drawer .wp-block-navigation-item__content',
		icon: 'arrow-right-up',
		pseudo: '::after',
		size: 22,
	},
];
for ( const { selector, icon, pseudo = '::before', size = 24 } of BINDINGS ) {
	if ( pseudo === '::before' ) {
		themeCss += `${ selector } svg {\n\tdisplay: none;\n}\n`;
	}
	themeCss += `${ selector }${ pseudo } {\n\tcontent: "";\n\tdisplay: block;\n\tflex: none;\n\twidth: ${ size }px;\n\theight: ${ size }px;\n\tbackground-color: currentColor;\n\t-webkit-mask: ${ dataUri( out[ icon ] ) } center / contain no-repeat;\n\tmask: ${ dataUri( out[ icon ] ) } center / contain no-repeat;\n}\n`;
}

const themeDir = resolve( root, '../../themes/sekeco/assets/css' );
mkdirSync( themeDir, { recursive: true } );
writeFileSync( resolve( themeDir, 'solar-icons.css' ), themeCss );

writeFileSync(
	resolve( root, 'assets/icons/LICENSE.txt' ),
	'Solar Icons by 480 Design (https://github.com/480-Design/Solar-Icon-Set), CC BY 4.0.\nPackaged via @iconify-json/solar.\n'
);

// eslint-disable-next-line no-console
console.log( `Wrote ${ ICONS.length } icons.` );
